  layout("layouts/main.tsx", [
    index("routes/home.tsx"),
    route("posts/:postId", "routes/post.tsx"),
    route("posts/:postId/edit", "routes/edit-post.tsx"),
  ]),
  route("about", "routes/about.tsx"),
];

